create table if not exists public.addon_settings(addon_key text primary key check(addon_key in ('connectx','zudo','business_health')),enabled boolean not null default false,title text not null,details text not null default '',unit_price numeric(12,2) not null default 0 check(unit_price>=0),min_days integer not null default 1,max_days integer not null default 365,min_daily_limit integer not null default 1,max_daily_limit integer not null default 1000,payment_info text not null default '',updated_by uuid references public.ems_owners(id),updated_at timestamptz not null default now(),check(min_days>0 and max_days>=min_days and min_daily_limit>0 and max_daily_limit>=min_daily_limit));
insert into public.addon_settings(addon_key,title) values('connectx','ConnectX'),('zudo','Zudo AI'),('business_health','AI Business Health') on conflict(addon_key) do nothing;
create table if not exists public.addon_purchases(id uuid primary key default gen_random_uuid(),admin_id uuid not null references public.administrators(id) on delete cascade,addon_key text not null check(addon_key in ('connectx','zudo','business_health')),validity_days integer not null check(validity_days>0),daily_limit integer not null check(daily_limit>0),unit_price numeric(12,2) not null,amount numeric(12,2) not null,payment_method public.payment_method not null,payment_number text not null,transaction_id text not null,status text not null default 'pending' check(status in ('pending','active','rejected','expired')),starts_at timestamptz,expires_at timestamptz,reviewed_at timestamptz,review_note text,created_at timestamptz not null default now());
create index if not exists addon_purchases_admin_key_idx on public.addon_purchases(admin_id,addon_key,status,expires_at desc);
revoke all on public.addon_settings,public.addon_purchases from anon,authenticated; alter table public.addon_settings enable row level security; alter table public.addon_purchases enable row level security;
